"""Derive SkyyPets/build_skyypets_0.4.22.py from SkyyPets 0.4.21 (SkyyPets/build_skyypets_0.4.21.py = the SET pin, itself GENERATED by
tools/pets_0_4_21_patch.py - never edit a generated script, edit this patch). Every anchor is asserted once; at the end every change is
undone on a copy and compared with 0.4.21 (tools/soundpass_gen.Patch). Line endings kept.
Run:  python tools/pets_0_4_22_patch.py   then   python SkyyPets/build_skyypets_0.4.22.py   (never --deploy)
      then  python SkyyPets/test_skyypets_0.4.22.py
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G

NOTE = '''0.4.22 (2026-10-30) = THE GEAR MANA % KEY (Augments round A2 fix round 3 with SkyyGear 0.3.52; Skyy's popup "Two augment types, Swift
  and Sage, give Mana %. That needs a small edit in Pets, Accessories, Gear and Skills so the Mana layers don't stack twice. What should we do
  with them?" -> "Add them now"; P0 X8). SkyyGear 0.3.52 writes ONE new additive MAX modifier on the Mana stat, skyygear_mana (the Swift /
  Sage augments' Mana %). PetBuff.pctKey learns it: the pet Health / Mana % (skyypet_health / skyypet_mana) is a % of the FLAT max, so it must
  never count Gear's Mana % layer as flat (that would compound the two % layers - the P5 critic rule). One line; nothing else changes.
  SAVED DATA: none. No config row, no migration, no new class / system / command.
  GO-TOGETHER (FLOOR): pins with SkyyGear 0.3.52 + SkyyAccessories 0.5.35 + SkyySkills 0.4.69. Rolling Pets back to 0.4.21 while Gear 0.3.52
  stays = the pet Mana % reads Gear's Mana % as flat Mana (a small double count, only for players wearing Swift / Sage); no data lost.
'''

P = G.Patch(os.path.join(ROOT, "SkyyPets", "build_skyypets_0.4.21.py"), os.path.join(ROOT, "SkyyPets", "build_skyypets_0.4.22.py"))
if "--out" in sys.argv:
    P.dst = os.path.abspath(sys.argv[sys.argv.index("--out") + 1])
assert P.has('VERSION = "0.4.21"') and P.has("public static String eggCol(") and not P.has("skyygear_mana"), "not the generated SkyyPets 0.4.21 script"
REG0, SYS0, CLS0 = P.s.count("registerCommand("), P.s.count("registerSystem("), P.s.count("= cls(")

P.rep('''"""SkyyPets 0.4.21 - build script (javassist via jpype, tools/skyybuild.py). GENERATED by tools/pets_0_4_21_patch.py from SkyyPets 0.4.20
(build_skyypets_0.4.20.py, the SET pin, itself generated by tools/pets_0_4_20_patch.py) - edit the patch, never this file.
Owner: Skyy (they/them). Run:  python SkyyPets/build_skyypets_0.4.21.py   -> SkyyPets/SkyyPets-0.4.21.jar
(no --deploy on purpose: tools/deploy_set.py installs the set once the round is ready). Test: python SkyyPets/test_skyypets_0.4.21.py
''', '''"""SkyyPets 0.4.22 - build script (javassist via jpype, tools/skyybuild.py). GENERATED by tools/pets_0_4_22_patch.py from SkyyPets 0.4.21
(build_skyypets_0.4.21.py, the SET pin, itself generated by tools/pets_0_4_21_patch.py) - edit the patch, never this file.
Owner: Skyy (they/them). Run:  python SkyyPets/build_skyypets_0.4.22.py   -> SkyyPets/SkyyPets-0.4.22.jar
(no --deploy on purpose: tools/deploy_set.py installs the set once the round is ready). Test: python SkyyPets/test_skyypets_0.4.22.py

''' + NOTE + '''
SkyyPets 0.4.21 (generated by tools/pets_0_4_21_patch.py from 0.4.20) - everything below is still true unless 0.4.22 above says otherwise:
''')
P.rep('VERSION = "0.4.21"\n', 'VERSION = "0.4.22"\n')
P.rep('''  return s.equals("skyypet_health") || s.equals("skyypet_mana") || s.equals("skyygear_hp") || s.equals("skyygear_ut_hp") || s.startsWith("skyyacc_")
''', '''  return s.equals("skyypet_health") || s.equals("skyypet_mana") || s.equals("skyygear_hp") || s.equals("skyygear_ut_hp") || s.equals("skyygear_mana") || s.startsWith("skyyacc_")
''')          # 0.4.22: + SkyyGear 0.3.52's augment Mana % layer

assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0 and P.s.count("= cls(") == CLS0, "0.4.22 adds no class, system or command"
assert P.s.count('"skyygear_mana"') == 1, "0.4.22: one percent-layer list in SkyyPets"
P.finish()
